import { FunnelChart } from '@absoluteui/components/funnel-chart';

const host = document.createElement('div');
document.body.append(host);
FunnelChart.create(host, {
  label: 'Checkout funnel',
  description: 'Last 30 days',
  stages: [
    { id: 'visits', label: 'Visits', value: 12000 },
    { id: 'cart', label: 'Added to cart', value: 4100 },
    { id: 'checkout', label: 'Checkout', value: 1900 },
    { id: 'paid', label: 'Paid', value: 1350 },
  ],
  color: 3,
});

import { FunnelChart, type FunnelStage } from '@absoluteui/components/funnel-chart';

const host = document.querySelector<HTMLElement>('#pipeline');
if (host) {
  const stages: FunnelStage[] = [
    { id: 'leads', label: 'Leads', value: 5400 },
    { id: 'qualified', label: 'Qualified', value: 2100 },
    { id: 'won', label: 'Won', value: null },
  ];
  const chart = FunnelChart.create(host, {
    label: 'Sales pipeline',
    stages,
    showConversion: false,
    valueFormat: { notation: 'compact' },
  });
  chart.update({ stages: stages.map((s) => (s.id === 'won' ? { ...s, value: 640 } : s)) });
}
